head.script:
scwin.regMode;
scwin.designTpCd;
scwin.gIsurCd;
scwin.gDtecDd;
scwin.gSeq;
scwin.gComAbbrv;
scwin.gChgTpNm;
scwin.gStrtDd;
scwin.gChgRsnNm;
scwin.gMisc;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.getParentValue();
        await scwin.init();
        await scwin.readInfo(); // 기본정보 불러오기
        $c.stf.doLogSave('ULDSTF30207.xml', SCREN_PROCS_TP_CD_01);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37307.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    txb_dtec_dd.hide(); // 적출일자 hidden
    txb_isur_cd.hide(); // SEQ hidden
    txb_seq.hide(); // SEQ hidden

    if (scwin.regMode === "APP" && js_jobtitl === "09") {
        // 검토상태 및 사용자가 팀장일때만...
        btn_Approv.show(""); // 승인버튼
        btn_Resv.show(""); // 유보버튼

    } else {
        btn_Approv.hide(); // 승인버튼
        btn_Resv.hide(); // 유보버튼

    }

    // 승인 또는 유보상태, 팀장이 로그인했을 경우 해당 문구 hidden 처리
    if (gChgStatCd === "30" || gChgStatCd === "40" || js_jobtitl === "09") {
        label_13.hide(); // 설명문

    } else {
        label_13.show(""); // 설명문

    }
    tbx_1.setValue(" " + scwin.gComAbbrv + "(" + scwin.gIsurCd + ")");
    tbx_2.setValue(" " + scwin.gChgTpNm);
    tbx_3.setValue(" " + scwin.gStrtDd.substr(0, 4) + "년 " + scwin.gStrtDd.substr(4, 2) + "월 " + scwin.gStrtDd.substr(6, 2) + "일");
    tbx_4.setValue(" " + scwin.gChgRsnNm);
    txa_misc.Text = " " + scwin.gMisc;

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MASTER.insertRow();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_inquiry_OnSuccess
 * @description inquiry On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37307.trs_inquiry_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_inquiry_OnFail
 * @description inquiry On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnFail = async function() {
    try {
        await $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37307.trs_inquiry_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37307.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Approv_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Approv_onclick = function() {
    try {
        scwin.approv();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37307.btn_Approv_onclick" });
    }
};

/**
 * @method
 * @name btn_Resv_onclick
 * @description 「유보」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Resv_onclick = function() {
    try {
        scwin.reject();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37307.btn_Resv_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readInfo
 * @description 선택한 정보 값 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readInfo = async function() {
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ByPass.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description 부모창에서 필요변수 저장
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gDtecDd = frame.opener.scwin.gDtecDd;
    scwin.gSeq = frame.opener.scwin.gSeq;
    gChgStatCd = frame.opener.gChgStatCd;
    scwin.regMode = frame.opener.scwin.regMode;
    scwin.gComAbbrv = frame.opener.scwin.gComAbbrv;
    scwin.gChgTpNm = frame.opener.scwin.gChgTpNm;
    scwin.gStrtDd = frame.opener.scwin.gStrtDd;
    scwin.gChgRsnNm = frame.opener.scwin.gChgRsnNm;
    scwin.gMisc = frame.opener.scwin.gMisc;
};

/**
 * @method
 * @name approv
 * @description 승인
 * @returns {void}
 * @hidden N
 */
scwin.approv = function() {
    let rtn = confirm('승인처리 하시겠습니까?');
    let vDtec_dd = txb_dtec_dd.getValue();
    let vIsur_cd = txb_isur_cd.getValue();
    let vSeq = txb_seq.getValue();
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "DTEC_DD", vDtec_dd); // 적출일자
        dts_MASTER.setCellData(1, "ISUR_CD", vIsur_cd); // 회사코드
        dts_MASTER.setCellData(1, "SEQ", vSeq); // SEQ
        dts_MASTER.setCellData(1, "REG_ID", js_id); // 등록자ID
        dts_MASTER.setCellData(1, "PRE_REVW_EXMPT_OBJ_CHG_STAT_CD", "30"); // 승인상태코드

        let url = "/ByPass.do?method=updateDesignExcludeHistReview";
        url += "&SCREN_ID=" + 'ULDSTF30207.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};

/**
 * @method
 * @name reject
 * @description 유보
 * @returns {void}
 * @hidden N
 */
scwin.reject = function() {
    let rtn = confirm('유보처리 하시겠습니까?');
    let vDtec_dd = txb_dtec_dd.getValue();
    let vIsur_cd = txb_isur_cd.getValue();
    let vSeq = txb_seq.getValue();
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "DTEC_DD", vDtec_dd); // 적출일자
        dts_MASTER.setCellData(1, "ISUR_CD", vIsur_cd); // 회사코드
        dts_MASTER.setCellData(1, "SEQ", vSeq); // SEQ
        dts_MASTER.setCellData(1, "REG_ID", js_id); // 등록자ID
        dts_MASTER.setCellData(1, "PRE_REVW_EXMPT_OBJ_CHG_STAT_CD", "40"); // 승인상태코드

        let url = "/ByPass.do?method=updateDesignExcludeHistReview";
        url += "&SCREN_ID=" + 'ULDSTF30207.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};
